package com.stocksense.inventory.delivery; import com.stocksense.inventory.stock.StockService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.Map; @RestController @RequestMapping("/api/deliveries") @RequiredArgsConstructor public class DeliveryController { private final StockService stock; record Req(Long productId,Long locationId,BigDecimal quantity,String customer){} @PostMapping("/validate") public Map<String,Object> validate(@RequestBody Req r,Authentication a){stock.deliver(r.productId(),r.locationId(),r.quantity(),a.getName());return Map.of("status","DONE","message","Delivery validated; stock decreased");} }
